-- V7: names and descriptions of the element choices, and the magic resistance (ME) of Elemi erő idézése (user decisions 2026-10-16).
--   Őselem idézése and Paraelem idézése: the choice input gets Hungarian labels (Ős tűz, ..., Elemi hideg, ...) and a description per value.
--   Elemi erő idézése: resisted by SFÉ again (V6 had set Elemi erő; the user's table says SFÉ).
-- Each update applies only while the stored value is still the old one, so an admin edit is never overwritten.
UPDATE mosaics
SET definition = jsonb_set(definition, '{inputs}', '[{"id":"element","label":"Őselem","type":"choice","values":["ostuz","osviz","osfold","oslevego"],"labels":{"ostuz":"Ős tűz","osviz":"Ős víz","osfold":"Ős föld","oslevego":"Ős levegő"},"descriptions":{"ostuz":"Önállóan létező anyag, így a természetes tűzzel ellentétben nem kell semmi, ami táplálja. A belsejében az erősségénél tizenötször nagyobb erősségű elemi hő van (kb. 80°+20°/tűz-E). A környezetbe szétsugárzott hő viszont már normális, és a fénye sem elemi fény (belül sem).","osviz":"Teljesen tiszta átlátszó víz. Megidézésekor a környezet hőmérsékletét veszi fel (nem jön vele az elemi hideg paraelem).","osfold":"Tökéletesen száraz, szürkés, porszerű anyag. Szemcséinek a mérete a homokéhoz hasonló. A normál levegőt is kiszorítja, így a légzés benne nehézkesebbé válik.","oslevego":"Tiszta levegő. Belélegezhető. Nem kíséri hő hatás (környezet hőmérséklete) a megidézésekor. A füst, légimérgek és egyéb anyagokat kiszorítja onnan, ahol van."}},{"id":"form","label":"Forma","type":"form"}]'::jsonb), updated_at = now()
WHERE id = 'anyagi-elemi-oselem-idezese' AND definition #> '{inputs}' = '[{"id":"element","label":"Őselem","type":"choice","values":["ostuz","osviz","osfold","oslevego"]},{"id":"form","label":"Forma","type":"form"}]'::jsonb;

UPDATE mosaics
SET definition = jsonb_set(definition, '{inputs}', '[{"id":"paraElement","label":"Paraelem","type":"choice","values":["ho","fagy","feny","setet"],"labels":{"ho":"Elemi hő","fagy":"Elemi hideg","feny":"Elemi fény","setet":"Elemi sötétség"},"descriptions":{"ho":"A tűz és a föld paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt felmelegít az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hideg.","fagy":"A levegő és a víz paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt lehűt az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hő.","feny":"A tűz és a levegő paraeleme. Megidézve az adott területen minden pont olyan fényességű lesz, mint az elemi fény erőssége (így az árnyékok eltűnnek). Ellentétes paraeleme az elemi sötétség.","setet":"A víz és a föld paraeleme. Megidézve az adott területen elnyeli a fényt, minden pontban olyan sötét lesz, mint ami az erősségnek megfelel. Ellentétes paraeleme az elemi fény."}},{"id":"form","label":"Forma","type":"form"}]'::jsonb), updated_at = now()
WHERE id = 'anyagi-elemi-paraelem-idezese' AND definition #> '{inputs}' = '[{"id":"paraElement","label":"Paraelem","type":"choice","values":["ho","fagy","feny","setet"]},{"id":"form","label":"Forma","type":"form"}]'::jsonb;

UPDATE mosaics
SET definition = jsonb_set(definition, '{resistance}', '{"kind":"armorSfe"}'::jsonb), updated_at = now()
WHERE id = 'anyagi-elemi-elemi-ero-idezese' AND definition #> '{resistance}' = '{"kind":"elementalForce"}'::jsonb;
